//! TPM manufacturer CA certificates compiled into Core, regenerated by tools/defguard_tpm_ca
//! from tpm-ca-certificates releases and Microsoft TrustedTpm.cab.

use std::{cmp::Ordering, collections::BTreeSet, sync::LazyLock};

use base64::{Engine, prelude::BASE64_STANDARD};
use chrono::{DateTime, TimeDelta, Utc};
use serde::{Deserialize, Serialize};
use thiserror::Error;
use x509_parser::parse_x509_certificate;

use crate::handlers::user::SortOrder;

const TPM_CA_CERTIFICATES_JSON: &str = include_str!("tpm_ca_certificates.json");
const STALE_AFTER: TimeDelta = TimeDelta::days(90);

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Deserialize, Serialize)]
#[cfg_attr(feature = "openapi", derive(utoipa::ToSchema))]
#[serde(rename_all = "snake_case")]
pub enum TpmCaKind {
    Root,
    Intermediate,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[cfg_attr(feature = "openapi", derive(utoipa::ToSchema))]
#[serde(rename_all = "kebab-case")]
pub enum TpmCaSource {
    TpmCaCertificates,
    Microsoft,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct BundleFile {
    generated_at: DateTime<Utc>,
    tpm_ca_certificates: ReleaseFile,
    microsoft_trusted_tpm: CabFile,
    certificates: Vec<CertificateFile>,
}

#[derive(Deserialize)]
struct ReleaseFile {
    tag: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct CabFile {
    cab_sha256: String,
    last_updated: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct CertificateFile {
    kind: TpmCaKind,
    vendor: String,
    common_name: String,
    organization: Option<String>,
    subject: String,
    issuer: String,
    serial_number: String,
    self_signed: bool,
    key_algorithm: String,
    not_before: DateTime<Utc>,
    not_after: DateTime<Utc>,
    sha256: String,
    spki_sha256: String,
    sources: Vec<TpmCaSource>,
    der: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[cfg_attr(feature = "openapi", derive(utoipa::ToSchema))]
pub struct TpmCaInfo {
    pub kind: TpmCaKind,
    pub vendor: String,
    pub common_name: String,
    pub organization: Option<String>,
    pub subject: String,
    pub issuer: String,
    // hex of the raw DER INTEGER, so a leading 00 sign byte is kept
    pub serial_number: String,
    pub self_signed: bool,
    pub key_algorithm: String,
    pub not_before: DateTime<Utc>,
    pub not_after: DateTime<Utc>,
    pub sha256: String,
    pub spki_sha256: String,
    pub sources: Vec<TpmCaSource>,
}

#[derive(Debug)]
pub struct TpmCaEntry {
    pub info: TpmCaInfo,
    pub der: Vec<u8>,
    search_text: String,
}

impl TpmCaEntry {
    fn from_file(file: CertificateFile) -> Result<Self, TpmBundleError> {
        let der = BASE64_STANDARD
            .decode(&file.der)
            .map_err(|source| TpmBundleError::Base64 {
                sha256: file.sha256.clone(),
                source,
            })?;
        if !sha256::digest(der.as_slice()).eq_ignore_ascii_case(&file.sha256) {
            return Err(TpmBundleError::Digest {
                sha256: file.sha256,
            });
        }
        if parse_x509_certificate(&der).is_err() {
            return Err(TpmBundleError::Certificate {
                sha256: file.sha256,
            });
        }

        let info = TpmCaInfo {
            kind: file.kind,
            vendor: file.vendor,
            common_name: file.common_name,
            organization: file.organization,
            subject: file.subject,
            issuer: file.issuer,
            serial_number: file.serial_number,
            self_signed: file.self_signed,
            key_algorithm: file.key_algorithm,
            not_before: file.not_before,
            not_after: file.not_after,
            sha256: file.sha256,
            spki_sha256: file.spki_sha256,
            sources: file.sources,
        };
        let search_text = [
            info.common_name.as_str(),
            info.organization.as_deref().unwrap_or_default(),
            &info.subject,
            &info.issuer,
            &info.vendor,
            &info.serial_number,
            &info.sha256,
        ]
        .join("\n")
        .to_lowercase();

        Ok(Self {
            info,
            der,
            search_text,
        })
    }

    fn matches(&self, filter: &TpmCaFilter, search: Option<&str>, now: DateTime<Utc>) -> bool {
        let info = &self.info;
        search.is_none_or(|search| self.search_text.contains(search))
            && filter.kind.is_none_or(|kind| info.kind == kind)
            && filter
                .vendor
                .as_deref()
                .is_none_or(|vendor| info.vendor.eq_ignore_ascii_case(vendor))
            && filter
                .source
                .is_none_or(|source| info.sources.contains(&source))
            && filter
                .expired
                .is_none_or(|expired| (info.not_after < now) == expired)
    }
}

#[derive(Debug, Error)]
pub enum TpmBundleError {
    #[error("Invalid TPM CA bundle: {0}")]
    Json(#[from] serde_json::Error),
    #[error("TPM CA certificate {sha256} is not valid base64: {source}")]
    Base64 {
        sha256: String,
        source: base64::DecodeError,
    },
    #[error("TPM CA certificate {sha256} does not match its SHA-256")]
    Digest { sha256: String },
    #[error("TPM CA certificate {sha256} is not a valid X.509 certificate")]
    Certificate { sha256: String },
    #[error("TPM CA bundle has no root certificates")]
    NoRoots,
}

/// Roots are the only trust anchors. Intermediates only help build a chain up to a root.
#[derive(Debug)]
pub struct TpmTrustBundle {
    pub generated_at: DateTime<Utc>,
    pub tpm_ca_certificates_tag: String,
    pub cab_sha256: String,
    pub cab_last_updated: String,
    entries: Vec<TpmCaEntry>,
}

#[derive(Debug, Default, Deserialize)]
pub struct TpmCaFilter {
    /// Case-insensitive substring of the common name, organization, subject, issuer, vendor,
    /// serial number or SHA-256.
    pub search: Option<String>,
    pub kind: Option<TpmCaKind>,
    pub vendor: Option<String>,
    pub source: Option<TpmCaSource>,
    pub expired: Option<bool>,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Deserialize, Serialize)]
#[cfg_attr(feature = "openapi", derive(utoipa::ToSchema))]
#[serde(rename_all = "snake_case")]
pub enum TpmCaSortKey {
    #[default]
    Name,
    Vendor,
    Kind,
    NotAfter,
}

#[derive(Debug, Default, Deserialize)]
pub struct TpmCaSort {
    #[serde(default)]
    pub sort_by: TpmCaSortKey,
    #[serde(default)]
    pub sort_order: SortOrder,
}

#[derive(Debug, PartialEq, Eq, Serialize)]
#[cfg_attr(feature = "openapi", derive(utoipa::ToSchema))]
pub struct TpmBundleSummary {
    pub generated_at: DateTime<Utc>,
    pub tpm_ca_certificates_tag: String,
    pub cab_sha256: String,
    pub cab_last_updated: String,
    pub roots: u32,
    pub intermediates: u32,
    pub stale: bool,
}

fn parse_bundle(json: &str) -> Result<TpmTrustBundle, TpmBundleError> {
    let file: BundleFile = serde_json::from_str(json)?;
    let entries = file
        .certificates
        .into_iter()
        .map(TpmCaEntry::from_file)
        .collect::<Result<Vec<_>, _>>()?;
    if !entries.iter().any(|e| e.info.kind == TpmCaKind::Root) {
        return Err(TpmBundleError::NoRoots);
    }
    Ok(TpmTrustBundle {
        generated_at: file.generated_at,
        tpm_ca_certificates_tag: file.tpm_ca_certificates.tag,
        cab_sha256: file.microsoft_trusted_tpm.cab_sha256,
        cab_last_updated: file.microsoft_trusted_tpm.last_updated,
        entries,
    })
}

static TPM_TRUST_BUNDLE: LazyLock<TpmTrustBundle> = LazyLock::new(|| {
    parse_bundle(TPM_CA_CERTIFICATES_JSON).expect("bundled TPM CA certificates must parse")
});

#[must_use]
pub fn tpm_trust_bundle() -> &'static TpmTrustBundle {
    &TPM_TRUST_BUNDLE
}

fn cmp_ignore_case(a: &str, b: &str) -> Ordering {
    a.chars()
        .flat_map(char::to_lowercase)
        .cmp(b.chars().flat_map(char::to_lowercase))
}

fn compare(a: &TpmCaInfo, b: &TpmCaInfo, key: TpmCaSortKey) -> Ordering {
    let by_name = || cmp_ignore_case(&a.common_name, &b.common_name);
    match key {
        TpmCaSortKey::Name => by_name(),
        TpmCaSortKey::Vendor => cmp_ignore_case(&a.vendor, &b.vendor).then_with(by_name),
        TpmCaSortKey::Kind => a.kind.cmp(&b.kind).then_with(by_name),
        TpmCaSortKey::NotAfter => a.not_after.cmp(&b.not_after),
    }
    .then_with(|| a.sha256.cmp(&b.sha256))
}

fn count(len: usize) -> u32 {
    u32::try_from(len).unwrap_or(u32::MAX)
}

impl TpmTrustBundle {
    #[must_use]
    pub fn entries(&self) -> &[TpmCaEntry] {
        &self.entries
    }

    pub fn roots(&self) -> impl Iterator<Item = &TpmCaEntry> {
        self.entries
            .iter()
            .filter(|e| e.info.kind == TpmCaKind::Root)
    }

    pub fn intermediates(&self) -> impl Iterator<Item = &TpmCaEntry> {
        self.entries
            .iter()
            .filter(|e| e.info.kind == TpmCaKind::Intermediate)
    }

    #[must_use]
    pub fn find(&self, sha256: &str) -> Option<&TpmCaEntry> {
        self.entries
            .iter()
            .find(|e| e.info.sha256.eq_ignore_ascii_case(sha256))
    }

    #[must_use]
    pub fn vendors(&self) -> Vec<&str> {
        self.entries
            .iter()
            .map(|e| e.info.vendor.as_str())
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect()
    }

    #[must_use]
    pub fn is_stale(&self, now: DateTime<Utc>) -> bool {
        now - self.generated_at > STALE_AFTER
    }

    #[must_use]
    pub fn summary(&self, now: DateTime<Utc>) -> TpmBundleSummary {
        let roots = self.roots().count();
        TpmBundleSummary {
            generated_at: self.generated_at,
            tpm_ca_certificates_tag: self.tpm_ca_certificates_tag.clone(),
            cab_sha256: self.cab_sha256.clone(),
            cab_last_updated: self.cab_last_updated.clone(),
            roots: count(roots),
            intermediates: count(self.entries.len() - roots),
            stale: self.is_stale(now),
        }
    }

    /// Returns one page of matching certificates and the total number of matches.
    #[must_use]
    pub fn query(
        &self,
        filter: &TpmCaFilter,
        sort: &TpmCaSort,
        offset: u32,
        limit: u32,
        now: DateTime<Utc>,
    ) -> (Vec<&TpmCaEntry>, u32) {
        let search = filter
            .search
            .as_deref()
            .map(str::trim)
            .filter(|search| !search.is_empty())
            .map(str::to_lowercase);
        let mut matches: Vec<_> = self
            .entries
            .iter()
            .filter(|entry| entry.matches(filter, search.as_deref(), now))
            .collect();
        matches.sort_by(|a, b| {
            let ordering = compare(&a.info, &b.info, sort.sort_by);
            match sort.sort_order {
                SortOrder::Asc => ordering,
                SortOrder::Desc => ordering.reverse(),
            }
        });
        let total = count(matches.len());
        let page = matches
            .into_iter()
            .skip(offset as usize)
            .take(limit as usize)
            .collect();
        (page, total)
    }
}

#[cfg(test)]
mod tests {
    use chrono::TimeZone;
    use rcgen::{CertificateParams, DnType, KeyPair};
    use serde_json::{Value, json};

    use super::*;
    use crate::handlers::pagination::PaginationParams;

    fn certificate(common_name: &str, vendor: &str, kind: &str, not_after: &str) -> Value {
        let key_pair = KeyPair::generate().expect("key pair");
        let mut params = CertificateParams::new(Vec::new()).expect("params");
        params
            .distinguished_name
            .push(DnType::CommonName, common_name);
        let der = params
            .self_signed(&key_pair)
            .expect("certificate")
            .der()
            .to_vec();
        json!({
            "kind": kind,
            "vendor": vendor,
            "commonName": common_name,
            "organization": null,
            "subject": format!("CN={common_name}"),
            "issuer": format!("CN={common_name}"),
            "serialNumber": "01",
            "selfSigned": true,
            "keyAlgorithm": "ECC P-256",
            "notBefore": "2020-01-01T00:00:00Z",
            "notAfter": not_after,
            "sha256": sha256::digest(der.as_slice()),
            "spkiSha256": "00",
            "sources": ["microsoft"],
            "der": BASE64_STANDARD.encode(&der),
        })
    }

    fn bundle_json(certificates: Vec<Value>) -> String {
        json!({
            "generatedAt": "2026-11-01T00:00:00Z",
            "tpmCaCertificates": { "tag": "2026-06-10" },
            "microsoftTrustedTpm": { "cabSha256": "ab", "lastUpdated": "23-October-2026" },
            "certificates": certificates,
        })
        .to_string()
    }

    fn sample_bundle() -> TpmTrustBundle {
        let mut tpm_ca = certificate(
            "Infineon OPTIGA RSA Root CA",
            "Infineon",
            "root",
            "2040-01-01T00:00:00Z",
        );
        tpm_ca["sources"] = json!(["tpm-ca-certificates", "microsoft"]);
        parse_bundle(&bundle_json(vec![
            tpm_ca,
            certificate(
                "Infineon OPTIGA ECC Manufacturing CA",
                "Infineon",
                "intermediate",
                "2030-01-01T00:00:00Z",
            ),
            certificate(
                "STM TPM EK Intermediate CA 05",
                "STMicroelectronics",
                "intermediate",
                "2020-06-01T00:00:00Z",
            ),
            certificate("Intel TPM EK root", "Intel", "root", "2049-01-01T00:00:00Z"),
            certificate(
                "Intel TPM EK root",
                "Intel",
                "intermediate",
                "2035-01-01T00:00:00Z",
            ),
        ]))
        .expect("sample bundle parses")
    }

    fn now() -> DateTime<Utc> {
        Utc.with_ymd_and_hms(2026, 11, 16, 0, 0, 0).unwrap()
    }

    fn query_page<'a>(
        bundle: &'a TpmTrustBundle,
        filter: &TpmCaFilter,
        sort: &TpmCaSort,
        pagination: PaginationParams,
    ) -> (Vec<&'a TpmCaEntry>, u32) {
        bundle.query(
            filter,
            sort,
            pagination.offset(),
            pagination.per_page(),
            now(),
        )
    }

    fn names(entries: &[&TpmCaEntry]) -> Vec<String> {
        entries.iter().map(|e| e.info.common_name.clone()).collect()
    }

    #[test]
    fn shipped_bundle_parses() {
        let bundle = parse_bundle(TPM_CA_CERTIFICATES_JSON).expect("shipped bundle parses");
        assert!(bundle.roots().next().is_some());
        assert!(bundle.intermediates().next().is_some());
        assert!(bundle.entries().iter().all(|e| {
            !e.info.vendor.is_empty()
                && !e.info.common_name.is_empty()
                && !e.info.sources.is_empty()
        }));
    }

    #[test]
    fn rejects_tampered_certificates() {
        let mut wrong_digest = certificate("A", "Intel", "root", "2040-01-01T00:00:00Z");
        wrong_digest["sha256"] = json!("00".repeat(32));
        assert!(matches!(
            parse_bundle(&bundle_json(vec![wrong_digest])),
            Err(TpmBundleError::Digest { .. })
        ));

        let mut bad_base64 = certificate("A", "Intel", "root", "2040-01-01T00:00:00Z");
        bad_base64["der"] = json!("not base64!");
        assert!(matches!(
            parse_bundle(&bundle_json(vec![bad_base64])),
            Err(TpmBundleError::Base64 { .. })
        ));

        let mut not_x509 = certificate("A", "Intel", "root", "2040-01-01T00:00:00Z");
        not_x509["der"] = json!(BASE64_STANDARD.encode([1, 2, 3]));
        not_x509["sha256"] = json!(sha256::digest([1u8, 2, 3].as_slice()));
        assert!(matches!(
            parse_bundle(&bundle_json(vec![not_x509])),
            Err(TpmBundleError::Certificate { .. })
        ));
    }

    #[test]
    fn rejects_bundle_without_roots() {
        let intermediate = certificate("A", "Intel", "intermediate", "2040-01-01T00:00:00Z");
        assert!(matches!(
            parse_bundle(&bundle_json(vec![intermediate])),
            Err(TpmBundleError::NoRoots)
        ));
    }

    #[test]
    fn search_is_case_insensitive_substring() {
        let bundle = sample_bundle();
        let filter = TpmCaFilter {
            search: Some("  optiga RSA ".into()),
            ..Default::default()
        };
        let (page, total) = query_page(
            &bundle,
            &filter,
            &TpmCaSort::default(),
            PaginationParams::default(),
        );
        assert_eq!(total, 1);
        assert_eq!(names(&page), ["Infineon OPTIGA RSA Root CA"]);

        let filter = TpmCaFilter {
            search: Some("stmicroelectronics".into()),
            ..Default::default()
        };
        let (_, total) = query_page(
            &bundle,
            &filter,
            &TpmCaSort::default(),
            PaginationParams::default(),
        );
        assert_eq!(total, 1);
    }

    #[test]
    fn filters_combine() {
        let bundle = sample_bundle();
        let query = |filter: TpmCaFilter| {
            let (page, total) = query_page(
                &bundle,
                &filter,
                &TpmCaSort::default(),
                PaginationParams::default(),
            );
            assert_eq!(total as usize, page.len());
            names(&page)
        };

        assert_eq!(
            query(TpmCaFilter {
                kind: Some(TpmCaKind::Root),
                vendor: Some("infineon".into()),
                ..Default::default()
            }),
            ["Infineon OPTIGA RSA Root CA"]
        );
        assert_eq!(
            query(TpmCaFilter {
                source: Some(TpmCaSource::TpmCaCertificates),
                ..Default::default()
            }),
            ["Infineon OPTIGA RSA Root CA"]
        );
        assert_eq!(
            query(TpmCaFilter {
                expired: Some(true),
                ..Default::default()
            }),
            ["STM TPM EK Intermediate CA 05"]
        );
        assert_eq!(
            query(TpmCaFilter {
                expired: Some(false),
                vendor: Some("Intel".into()),
                kind: Some(TpmCaKind::Intermediate),
                ..Default::default()
            }),
            ["Intel TPM EK root"]
        );
    }

    #[test]
    fn sorting_is_stable_across_pages() {
        let bundle = sample_bundle();
        let sort = TpmCaSort {
            sort_by: TpmCaSortKey::Name,
            sort_order: SortOrder::Asc,
        };
        let (all, total) = query_page(
            &bundle,
            &TpmCaFilter::default(),
            &sort,
            PaginationParams::new(1, 100),
        );
        assert_eq!(total, 5);
        assert_eq!(
            names(&all),
            [
                "Infineon OPTIGA ECC Manufacturing CA",
                "Infineon OPTIGA RSA Root CA",
                "Intel TPM EK root",
                "Intel TPM EK root",
                "STM TPM EK Intermediate CA 05",
            ]
        );
        assert!(all[2].info.sha256 < all[3].info.sha256);

        let paged: Vec<_> = (1..=3)
            .flat_map(|page| {
                let (entries, total) = query_page(
                    &bundle,
                    &TpmCaFilter::default(),
                    &sort,
                    PaginationParams::new(page, 2),
                );
                assert_eq!(total, 5);
                entries
            })
            .collect();
        assert_eq!(
            paged.iter().map(|e| &e.info.sha256).collect::<Vec<_>>(),
            all.iter().map(|e| &e.info.sha256).collect::<Vec<_>>()
        );

        let (beyond, total) = query_page(
            &bundle,
            &TpmCaFilter::default(),
            &sort,
            PaginationParams::new(4, 2),
        );
        assert!(beyond.is_empty());
        assert_eq!(total, 5);

        let desc = TpmCaSort {
            sort_by: TpmCaSortKey::NotAfter,
            sort_order: SortOrder::Desc,
        };
        let (latest, _) = query_page(
            &bundle,
            &TpmCaFilter::default(),
            &desc,
            PaginationParams::new(1, 1),
        );
        assert_eq!(
            latest[0].info.not_after.to_rfc3339(),
            "2049-01-01T00:00:00+00:00"
        );
    }

    #[test]
    fn vendors_are_sorted_and_unique() {
        assert_eq!(
            sample_bundle().vendors(),
            ["Infineon", "Intel", "STMicroelectronics"]
        );
    }

    #[test]
    fn find_ignores_case() {
        let bundle = sample_bundle();
        let sha256 = bundle.entries()[0].info.sha256.to_uppercase();
        assert!(bundle.find(&sha256).is_some());
        assert!(bundle.find("missing").is_none());
    }

    #[test]
    fn stale_after_ninety_days() {
        let bundle = sample_bundle();
        let limit = bundle.generated_at + TimeDelta::days(90);
        assert!(!bundle.is_stale(limit));
        assert!(bundle.is_stale(limit + TimeDelta::seconds(1)));

        let summary = bundle.summary(limit);
        assert_eq!(summary.roots, 2);
        assert_eq!(summary.intermediates, 3);
        assert!(!summary.stale);
    }
}
